                        consentModal: {
                            title: "Sīkdatņu iestatījumi",
                            description: "Mēs izmantojam savas un trešo pušu sīkdatnes apmeklējuma drošībai un ievācam personas datus, lai identificētu pakalpojumu saņēmējus. 

Jūs varat piekrist vietnes lietošanas un privātuma noteikumiem un visām sīkdatnēm, noklikšķinot uz “Apstiprināt”, vai noraidīt sīkdatnes, noklikšķinot uz “Noraidīt”. 

Ja tīmekļa vietnes lietotājs noklikšķina uz pogas “Noraidīt”, tīmekļa vietnē tiek saglabātas obligātās sīkdatnes, kas ir nepieciešamas tīmekļa vietnes darbībai un kuru izmantošanai nav nepieciešama lietotāja piekrišana.",
                            closeIconLabel: "",
                            acceptAllBtn: "Apstiprināt",
                            acceptNecessaryBtn: "Noraidīt",
                            showPreferencesBtn: "Uzstādījumi",
                            footer: "Vietnes lietošanas un privātuma noteikumi"
                        },
                        preferencesModal: {
                            title: "Sīkdatņu iestatījumi",
                            closeIconLabel: "Aizvērt logu",
                            acceptAllBtn: "Pieņemt visu",
                            acceptNecessaryBtn: "Noraidīt visu",
                            savePreferencesBtn: "Saglabāt uzstādījumus",
                            serviceCounterLabel: "",
                            sections: [
                                {
                                    title: "Obligātās",
                                    description: "Obligātās sīkdatnes nodrošina vietnes pamatfunkcijas, piemēram, pieteikšanos un konta pārvaldību. Bez obligātajām sīkdatnēm tīmekļa vietni nav iespējams pienācīgi izmantot.",
                                    linkedCategory: "necessary"
                                },
                                {
                                    title: "Analīze",
                                    description: "Analītiskās sīkdatnes tiek izmantotas, lai redzētu, kā apmeklētāji izmanto vietni, piemēram, analītiskās sīkdatnes. Šīs sīkdatnes nevar izmantot, lai tieši identificētu konkrētu apmeklētāju.",
                                    linkedCategory: "analytics"
                                }
                            ]
                        }
                    }
                }
            },
            disablePageInteraction: true
        });

