footer.script:
(function () {
    var tripForms = document.querySelectorAll('.trip-request-form');

    var showTripMessage = function (form, text, isError) {
        var messageEl = form.querySelector('.trip-request-form-message');

        if (!messageEl) {
            return;
        }

        messageEl.classList.remove('is-error', 'is-success');
        messageEl.classList.add(isError ? 'is-error' : 'is-success');
        messageEl.textContent = text;
    };

    var setTripLoading = function (form, isLoading) {
        var submitButton = form.querySelector('button[type="submit"]');

        form.classList[isLoading ? 'add' : 'remove']('is-loading');

        if (submitButton) {
            submitButton.disabled = isLoading;
        }
    };

    var buildChildrenValue = function (form) {
        var childrenCountInput = form.querySelector('.children-count');
        var childrenCount = parseInt(childrenCountInput ? childrenCountInput.value : '0', 10) || 0;
        var ageInputs = form.querySelectorAll('.child-ages-list input, .child-ages-list select');
        var childAges = [];

        Array.prototype.forEach.call(ageInputs, function (ageInput) {
            var ageValue = String(ageInput.value || '').trim();

            if (ageValue !== '') {
                childAges.push(ageValue);
            }
        });

        if (!childrenCount) {
            return '';
        }

        if (childAges.length) {
            return childrenCount + ' (' + childAges.join(', ') + ')';
        }

        return String(childrenCount);
    };

    Array.prototype.forEach.call(tripForms, function (form) {
        form.addEventListener('submit', function (event) {
            event.preventDefault();

            var emailInput = form.querySelector('input[name="request[email]"]');
            var dateFromInput = form.querySelector('input[name="request[date_from]"]');
            var dateToInput = form.querySelector('input[name="request[date_to]"]');
            var dateDisplayInput = form.querySelector('.datepicker-input input.datepicker');
            var descriptionInput = form.querySelector('textarea[name="request[description]"]');
            var email = emailInput ? String(emailInput.value || '').trim() : '';
            var dateFrom = dateFromInput ? String(dateFromInput.value || '').trim() : '';
            var dateTo = dateToInput ? String(dateToInput.value || '').trim() : '';
            var dateDisplay = dateDisplayInput ? String(dateDisplayInput.value || '').trim() : '';
            var description = descriptionInput ? String(descriptionInput.value || '').trim() : '';
            var invalidEmailMessage = form.getAttribute('data-invalid-email-message') || 'Invalid email address';
            var invalidDatesMessage = form.getAttribute('data-invalid-dates-message') || 'Please select dates';
            var invalidDescriptionMessage = form.getAttribute('data-invalid-description-message') || 'Please enter a description';
            var genericErrorMessage = form.getAttribute('data-generic-error-message') || 'Something went wrong';
            var successMessage = form.getAttribute('data-success-message') || 'Submitted';
            var childrenField = form.querySelector('.trip-request-children-field');
            var recaptchaField = form.querySelector('input[name="g-recaptcha-response"]');
            var actionUrl = form.getAttribute('action') || '/lv/custom-request';
            var formData;
            var xhr;

            var clearInvalids = function () {
                var invalids = form.querySelectorAll('.input-wrapper.is-invalid');
                Array.prototype.forEach.call(invalids, function (wrapper) {
                    wrapper.classList.remove('is-invalid');
                });
            };

            var markInvalid = function (field) {
                if (!field) {
                    return;
                }

                var wrapper = field.closest('.input-wrapper');
                if (wrapper) {
                    wrapper.classList.add('is-invalid');
                }
            };

            clearInvalids();

            if (!email || (emailInput && !emailInput.checkValidity())) {
                markInvalid(emailInput);
                showTripMessage(form, invalidEmailMessage, true);
                return;
            }

            if ((!dateFrom || !dateTo) && !dateDisplay) {
                markInvalid(dateDisplayInput || dateFromInput || dateToInput);
                showTripMessage(form, invalidDatesMessage, true);
                return;
            }

            if (!description) {
                markInvalid(descriptionInput);
                showTripMessage(form, invalidDescriptionMessage, true);
                return;
            }

            if (childrenField) {
                childrenField.value = buildChildrenValue(form);
            }

            if (recaptchaField && !String(recaptchaField.value || '').trim()) {
                recaptchaField.value = 'footer-trip-request';
            }

            formData = new FormData(form);
            setTripLoading(form, true);

            xhr = new XMLHttpRequest();
            xhr.open('POST', actionUrl, true);

            xhr.onload = function () {
                var responseText = String(xhr.responseText || '').trim();
                var isSuccess = xhr.status >= 200 && xhr.status < 300 && !/stop it!/i.test(responseText);

                if (isSuccess) {
                    showTripMessage(form, successMessage, false);
                    form.reset();
                    return;
                }

                showTripMessage(form, responseText || genericErrorMessage, true);
            };

            xhr.onerror = function () {
                showTripMessage(form, genericErrorMessage, true);
            };

            xhr.onloadend = function () {
                setTripLoading(form, false);
            };

            xhr.send(formData);
        });
    });

    var forms = document.querySelectorAll('.newsletter-form');

    if (!forms.length) {
        return;
    }

    var showMessage = function (form, text, isError) {
        var messageEl = form.querySelector('.newsletter-form-message');

        if (!messageEl) {
            return;
        }

        messageEl.classList.remove('is-error', 'is-success');
        messageEl.classList.add(isError ? 'is-error' : 'is-success');
        messageEl.textContent = text;
    };

    var setLoading = function (form, isLoading) {
        var submitButton = form.querySelector('button[type="submit"]');

        form.classList[isLoading ? 'add' : 'remove']('is-loading');

        if (submitButton) {
            submitButton.disabled = isLoading;
        }
    };

    Array.prototype.forEach.call(forms, function (form) {
        form.addEventListener('submit', function (event) {
            event.preventDefault();

            var emailInput = form.querySelector('input[name="subscribe"]');
            var email = emailInput ? emailInput.value.trim() : '';
            var honeypotInput = form.querySelector('input[name="website"]');
            var honeypotValue = honeypotInput ? honeypotInput.value.trim() : '';
            var formTimestampInput = form.querySelector('input[name="form_ts"]');
            var formTimestampValue = formTimestampInput ? formTimestampInput.value.trim() : '';
            var formTokenInput = form.querySelector('input[name="form_token"]');
            var formTokenValue = formTokenInput ? formTokenInput.value.trim() : '';
            var invalidEmailMessage = form.getAttribute('data-invalid-email-message') || 'Invalid email address';
            var genericErrorMessage = form.getAttribute('data-generic-error-message') || 'Something went wrong';
            var successMessage = form.getAttribute('data-success-message') || 'Subscribed';

            if (!email || (emailInput && !emailInput.checkValidity())) {
                showMessage(form, invalidEmailMessage, true);
                return;
            }

            setLoading(form, true);

            var xhr = new XMLHttpRequest();
            xhr.open('POST', '/lv/action/subscribe', true);
            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');

            xhr.onload = function () {
                var responseText = (xhr.responseText || '').trim();
                var isSuccess = xhr.status >= 200 && xhr.status < 300 && !responseText;

                if (isSuccess) {
                    showMessage(form, successMessage, false);
                    form.reset();
                    return;
                }

                showMessage(form, responseText || genericErrorMessage, true);
            };

            xhr.onerror = function () {
                showMessage(form, genericErrorMessage, true);
            };

            xhr.onloadend = function () {
                setLoading(form, false);
            };

            xhr.send(
                'subscribe=' + encodeURIComponent(email) +
                '&website=' + encodeURIComponent(honeypotValue) +
                '&form_ts=' + encodeURIComponent(formTimestampValue) +
                '&form_token=' + encodeURIComponent(formTokenValue)
            );
        });
    });
})();

