            var _captchaTries = 0;

            function recaptchaOnload() {
                _captchaTries++;

                if (_captchaTries > 9)
                    return;
                if ($('.g-recaptcha').length > 0) {

                    $('.g-recaptcha').each(function() {
                        var thisElem = $(this);

                        window.grecaptcha.render(thisElem[0], {
                            sitekey: '6LenL9ceAAAAAJ36eYuii10Mj7TUXPXXL_iMnFBH',
                            callback: function() {
                                $(thisElem).closest('form').attr('data-captcha-valid', 1);
                            }
                        });
                    })

                    return;
                }

                window.setTimeout(recaptchaOnload, 1000);
            }


        $(function() {
            if ($('.coupon-gallery-image').length) {
                $('.coupon-gallery-image').magnificPopup({
                    type:'image',
                    gallery: {
                        enabled: true
                    },
                })
            }

            $('.mobile-nav-body .has-submenu').each(function() {
                var $item = $(this);
                var $parentLink = $item.children('a').first();

                if (!$parentLink.length) {
                    return;
                }

                var $submenuWrapper = $item.find('.submenu-wrapper').first();
                if (!$submenuWrapper.length) {
                    return;
                }

                if ($submenuWrapper.find('.submenu-parent-link').length) {
                    return;
                }

                var $targetHeading = $submenuWrapper.find('h3').first();
                var $insertionPoint = $targetHeading.length ? $targetHeading : $submenuWrapper.find('.submenu-content-wrapper').first();

                if (!$insertionPoint.length) {
                    return;
                }

                if ( ! $parentLink.hasClass('more-menu-item')) {
                    var $clonedLink = $parentLink.clone();
                    $clonedLink.find('i').remove();
                    $clonedLink.addClass('submenu-parent-link');
                    $clonedLink.text($clonedLink.attr('data-alter'));

                    var $parentContainer = $('
').append($clonedLink);
                }

                if ($targetHeading.length) {
                    $parentContainer.insertBefore($targetHeading);
                } else {
                    $insertionPoint.prepend($parentContainer);
                }
            });

            function normalizeMenuTitle(text) {
                return $.trim(text || '');
            }

            function isTargetMobileSection(text) {
                var title = normalizeMenuTitle(text);
                return title === 'Eiropa' || title === 'Azija, Amerika' || title === 'Āzija, Amerika';
            }

            function mergeAndSortMobileSubmenu($section) {
                var $container = $section.children('div').first();
                if (!$container.length) {
                    return;
                }

                var $cols = $container.find('.submenu-column');
                if ($cols.length <= 1) {
                    return;
                }

                var items = $cols.find('li').get();
                if (!items.length) {
                    return;
                }

                items.sort(function(a, b) {
                    var aText = $(a).text().trim();
                    var bText = $(b).text().trim();
                    return aText.localeCompare(bText, 'lv', { sensitivity: 'base' });
                });

                var $newCol = $('
');
                var firstClass = $container.find('ul').first().attr('class');
                var $newUl = $('');
                if (firstClass) {
                    $newUl.attr('class', firstClass);
                }

                $(items).each(function() {
                    $newUl.append(this);
                });

                $newCol.append($newUl);
                $container.empty().append($newCol);
            }

            function normalizeMobileMenuColumns() {
                $('.mobile-nav-body .submenu-section').each(function() {
                    var $section = $(this);
                    var $title = $section.find('h3').first();
                    if (!$title.length) {
                        return;
                    }
                    if (!isTargetMobileSection($title.text())) {
                        return;
                    }
                    mergeAndSortMobileSubmenu($section);
                });
            }

            normalizeMobileMenuColumns();

            $('body').on('click', '.mobile-menu-toggle', function() {
                setTimeout(normalizeMobileMenuColumns, 0);
            });

            function setMobilePhoneModalOffset() {
                var $header = $('header').first();
                if (!$header.length) {
                    return;
                }
                var headerHeight = $header.outerHeight();
                document.documentElement.style.setProperty('--mobile-phone-modal-top', headerHeight + 'px');
            }

            function closeMobilePhoneModal() {
                $('#mobile-phone-modal').removeClass('is-open').attr('aria-hidden', 'true');
                $('body').removeClass('mobile-phone-modal-open');
                $('.mobile-phone-toggle').removeClass('is-open').attr('aria-expanded', 'false');
            }

            function openMobilePhoneModal() {
                $('#mobile-phone-modal').addClass('is-open').attr('aria-hidden', 'false');
                $('body').addClass('mobile-phone-modal-open');
                $('.mobile-phone-toggle').addClass('is-open').attr('aria-expanded', 'true');
            }

            setMobilePhoneModalOffset();
            $(window).on('resize', function() {
                setMobilePhoneModalOffset();
            });

            $('body').on('click', '.mobile-phone-toggle', function() {
                var $modal = $('#mobile-phone-modal');
                if ($modal.hasClass('is-open')) {
                    closeMobilePhoneModal();
                } else {
                    openMobilePhoneModal();
                }
            });

            $('body').on('click', '[data-mobile-phone-close]', function() {
                closeMobilePhoneModal();
            });

            $(document).on('keydown', function(e) {
                if (e.key === 'Escape') {
                    closeMobilePhoneModal();
                }
            });
        });

